    h, w = len(grid), len(grid[0])

    # Full-width colored rows encode horizontal phases; zero rows are gaps.
    colored_rows = [r for r, row in enumerate(grid) if row[0] != 0 and all(v == row[0] for v in row)]
    if colored_rows and all(all(v == 0 for v in grid[r]) or (grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])) for r in range(h)):
        period = len(colored_rows)
        phases = {}
        for r in colored_rows:
            phases[r % period] = grid[r][0]
        return [[phases[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal bars encode phases by their anti-diagonal (row + column).
    diagonals = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color != 0:
                diagonals.setdefault(r + c, color)
    period = len(diagonals)
    phases = {s % period: color for s, color in diagonals.items()}
    return [[phases[(r + c) % period] for c in range(w)] for r in range(h)]
